import sys

def lcs_length(a: str, b: str) -> int:
    if not a or not b:
        return 0
    if len(a) > len(b):
        a, b = b, a
    # Bit-parallel LCS (Allison-Dill / Hyyro)
    masks = {}
    for i, ch in enumerate(a):
        masks[ch] = masks.get(ch, 0) | (1 << i)

    S = (1 << len(a)) - 1
    for ch in b:
        pm = masks.get(ch, 0)
        u = S & pm
        S = (S + u) | (S - u)

    # Length is number of 0 bits in the lower len(a) bits of S
    return len(a) - (S & ((1 << len(a)) - 1)).bit_count()

def main():
