        ba = a.encode('ascii')[::-1]
        bb = b.encode('ascii')
        masks = [0] * 128
        tt = _TRANS_TABLES
        b_trans = ba.translate
        for ch in set(ba) & set(bb):
            masks[ch] = int(b_trans(tt[ch]), 2)
        full = (1 << len(a)) - 1
        S = full
        for byte in bb:
            u = S & masks[byte]
            S = (S + u) | (S - u)
        return len(a) - (S & full).bit_count()

