    bit = 1
    for ch in a:
        masks[ch] |= bit
        bit <<= 1
    full = bit - 1
    S = full
    masks_get = masks.get
    for ch in b:
        pm = masks_get(ch, 0)
        u = S & pm
        S = (S + u) | (S - u)
    return len(a) - (S & full).bit_count()

